SELECT *, LAST_VALUE(stock_qty, TRUE) OVER w_part AS last_known_stock_qty, DENSE_RANK() OVER w_ordered AS stock_qty_dense_rank, ROW_NUMBER() OVER w_grp AS event_seq FROM products WINDOW w_part AS (PARTITION BY category ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered AS (PARTITION BY category, brand ORDER BY stock_qty NULLS FIRST), w_grp AS (PARTITION BY supplier_id ORDER BY stock_qty DESC, id);
